import java.util.*;

class Solution {
  public boolean gcdSort(int[] nums) {
    int max = 100000;
    DSU dsu = new DSU(max + 1);
    for (int x : nums) for (int p : factors(x)) dsu.union(x, p);
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    for (int i = 0; i < nums.length; i++)
      if (dsu.find(nums[i]) != dsu.find(sorted[i])) return false;
    return true;
  }

  private List<Integer> factors(int x) {
    List<Integer> result = new ArrayList<>();
    for (int p = 2; p * p <= x; p++)
      if (x % p == 0) {
        result.add(p);
        while (x % p == 0) x /= p;
      }
    if (x > 1) result.add(x);
    return result;
  }

  static class DSU {
    int[] parent;

    DSU(int n) {
      parent = new int[n];
      for (int i = 0; i < n; i++) parent[i] = i;
    }

    int find(int x) {
      return parent[x] == x ? x : (parent[x] = find(parent[x]));
    }

    void union(int a, int b) {
      a = find(a);
      b = find(b);
      if (a != b) parent[a] = b;
    }
  }
}
